import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useNotification } from '../components/NotificationContext';

const Signup = () => {
  const { signup, loginWithGoogle } = useAuth();
  const navigate = useNavigate();
  const { addNotification } = useNotification();
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    gender: 'neutral'
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    // Validation
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }
    
    setIsLoading(true);
    
    try {
      const result = await signup({
        name: formData.name,
        email: formData.email,
        password: formData.password,
        gender: formData.gender
      });
      
      if (!result.success) {
        setError(result.error || 'Signup failed. Please try again.');
        addNotification('Signup failed. Please try again.', 'error');
        return;
      }
      
      addNotification('Account created successfully!', 'success');
      navigate('/onboarding');
    } catch (error) {
      console.error('Signup error:', error);
      setError('An unexpected error occurred. Please try again.');
      addNotification('Signup failed. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };
  
  const handleGoogleLogin = async () => {
    setError('');
    setIsLoading(true);
    
    try {
      const result = await loginWithGoogle();
      
      if (!result.success) {
        setError(result.error || 'Google signup failed. Please try again.');
        addNotification('Google signup failed. Please try again.', 'error');
        return;
      }
      
      // Note: OAuth redirect will happen here
    } catch (error) {
      console.error('Google signup error:', error);
      setError('An unexpected error occurred. Please try again.');
      addNotification('Google signup failed. Please try again.', 'error');
      setIsLoading(false);
    }
  };
  
  const handleLogin = () => {
    navigate('/login');
  };
  
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 py-12 px-4 sm:px-6 lg:px-8">
      <motion.div 
        className="max-w-md w-full space-y-8 p-8 bg-gray-800 rounded-2xl shadow-xl backdrop-blur-lg bg-opacity-50 border border-gray-700"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <div className="text-center">
          <motion.h2 
            className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.5 }}
          >
            Create your account
          </motion.h2>
          <p className="mt-2 text-sm text-white/60">Start tracking your study journey today</p>
        </div>
        
        {error && (
          <motion.div 
            className="bg-red-500/20 border border-red-500/50 text-white p-3 rounded-lg text-sm"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
          >
            {error}
          </motion.div>
        )}
        
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label htmlFor="name" className="sr-only">Full Name</label>
              <input 
                id="name" 
                name="name" 
                type="text" 
                required 
                className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                placeholder="Full Name"
                value={formData.name}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <label htmlFor="email" className="sr-only">Email address</label>
              <input 
                id="email" 
                name="email" 
                type="email" 
                autoComplete="email" 
                required 
                className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                placeholder="Email address"
                value={formData.email}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <label htmlFor="password" className="sr-only">Password</label>
              <input 
                id="password" 
                name="password" 
                type="password" 
                required 
                className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <label htmlFor="confirmPassword" className="sr-only">Confirm Password</label>
              <input 
                id="confirmPassword" 
                name="confirmPassword" 
                type="password" 
                required 
                className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                placeholder="Confirm Password"
                value={formData.confirmPassword}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <label htmlFor="gender" className="sr-only">Gender</label>
              <select 
                id="gender" 
                name="gender" 
                className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                value={formData.gender}
                onChange={handleChange}
              >
                <option value="neutral">Prefer not to say</option>
                <option value="male">Male</option>
                <option value="female">Female</option>
                <option value="other">Other</option>
              </select>
            </div>
          </div>

          <motion.button
            type="submit"
            className="neural-button w-full py-3 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-500 text-white font-medium hover:from-cyan-600 hover:to-blue-600 transition-all duration-200"
            whileHover={{ scale: 1.02, boxShadow: '0 0 15px rgba(100, 200, 255, 0.5)' }}
            whileTap={{ scale: 0.98 }}
            disabled={isLoading}
          >
            {isLoading ? (
              <span className="flex items-center justify-center">
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Creating account...
              </span>
            ) : (
              'Sign Up'
            )}
          </motion.button>
          
          <div className="mt-4 relative flex items-center justify-center">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-gray-700"></div>
            </div>
            <div className="relative px-4 bg-gray-800">
              <span className="text-sm text-gray-400">Or continue with</span>
            </div>
          </div>
          
          <motion.button
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex justify-center items-center py-3 px-4 border border-gray-700 rounded-lg shadow-sm bg-white text-gray-800 font-medium hover:bg-gray-50 transition-all duration-200"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            disabled={isLoading}
          >
            <svg className="h-5 w-5 mr-2" viewBox="0 0 24 24">
              <path
                d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                fill="#4285F4"
              />
              <path
                d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                fill="#34A853"
              />
              <path
                d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                fill="#FBBC05"
              />
              <path
                d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                fill="#EA4335"
              />
            </svg>
            Google
          </motion.button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-white/60 text-sm">
            Already have an account?{' '}
            <button type="button" onClick={handleLogin} className="text-neural-primary hover:text-neural-secondary transition-colors">
              Log in
            </button>
          </p>
        </div>
      </motion.div>
    </div>
  );
};

export default Signup; 